export const courseById=Object.fromEntries(courses.map(course=>[course.id,course]));
export const chapterById=Object.fromEntries(courses.flatMap(course=>course.chapters.map(chapter=>[chapter.id,chapter])));
export function courseTopicIds(courseId){const course=Object.hasOwn(courseById,courseId)?courseById[courseId]:null;return course?[...new Set([...course.chapters.flatMap(chapter=>chapter.topicIds),...course.backgroundTopicIds])]:[];}
